</script>
<template><aside class="recipe" aria-label="增强配方面板"><header><h2>航空航天图像增强</h2><p>先选配方，再查看真实样例。确认后生成独立副本，原图继续保留。</p></header><p v-if="store.metaError" role="alert">{{store.metaError}} <button @click="store.loadMeta">重试</button></p><p v-if="store.metaLoading">正在读取配方…</p><fieldset :disabled="store.running"><button v-for="preset in store.presets" :key="preset.name" class="preset" :class="{active:store.sourceName===preset.name&&!store.edited}" :aria-pressed="store.sourceName===preset.name&&!store.edited" @click="store.applyPreset(preset)"><b>{{preset.title}}</b><span>{{preset.reason}}</span><small>{{store.sourceName===preset.name&&!store.edited?'✓ 已选择':'使用这个配方'}}</small></button>
